BEGIN;
CREATE SCHEMA delivery_test;CREATE FUNCTION delivery_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;CREATE FUNCTION delivery_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;GRANT USAGE ON SCHEMA delivery_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA delivery_test TO anon,authenticated;
INSERT INTO auth.users(id,email) VALUES('2b000000-0000-4000-8000-000000000001','delivery@example.invalid');INSERT INTO public.companies(id,nome,created_by) VALUES('1b000000-0000-4000-8000-000000000001','Delivery fixture','2b000000-0000-4000-8000-000000000001'),('1b000000-0000-4000-8000-000000000002','Other fixture','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1b000000-0000-4000-8000-000000000001','2b000000-0000-4000-8000-000000000001','administrador','admin_empresa','2b000000-0000-4000-8000-000000000001');
INSERT INTO public.veiculos(id,company_id,placa,tipo,marca_modelo,km_atual,ano_fabricacao,ano_modelo,chassi,renavam) VALUES('3b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','EXL0001','caminhao','Volvo FH',1000,2022,2023,'9BWZZZ377VT004251','12345678901');
SELECT set_config('request.jwt.claim.sub','2b000000-0000-4000-8000-000000000001',true);
INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,onboarding_profile) VALUES('4b000000-0000-4000-8000-000000000001','1b000000-0000-4000-8000-000000000001','Delivery workshop','11987654321','{"prazo_entrega_dias":3}');

INSERT INTO public.maintenance_partners(id,company_id,razao_social,whatsapp,status) VALUES('4b000000-0000-4000-8000-000000000002','1b000000-0000-4000-8000-000000000001','Second workshop','21987654321','ativo'),('4b000000-0000-4000-8000-000000000003','1b000000-0000-4000-8000-000000000001','No contact',NULL,'ativo'),('4b000000-0000-4000-8000-000000000004','1b000000-0000-4000-8000-000000000001','Inactive workshop','31987654321','inativo'),('4b000000-0000-4000-8000-000000000005','1b000000-0000-4000-8000-000000000002','Other company','41987654321','ativo');

SET LOCAL ROLE authenticated;
SELECT set_config('delivery_test.os',public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','create','{"vehicle_id":"3b000000-0000-4000-8000-000000000001","partner_id":"4b000000-0000-4000-8000-000000000001","tipo":"corretiva","prioridade":"media","descricao_problema":"Repair required","km_abertura":1000}')->>'id',true);
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','item_save',jsonb_build_object('id',current_setting('delivery_test.os'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.os')::uuid),'tipo','servico','descricao','Reparo real de teste','quantidade',1,'valor_unitario',100));
SELECT public.maintenance_order_command('1b000000-0000-4000-8000-000000000001','budget',jsonb_build_object('id',current_setting('delivery_test.os'),'version',(SELECT version FROM public.maintenance_orders WHERE id=current_setting('delivery_test.os')::uuid),'decisao','aprovado','observacao','Approved fixture','prazo_entrega_dias',3));

SELECT set_config('delivery_test.invoice',public.maintenance_finance_command('1b000000-0000-4000-8000-000000000001','create',jsonb_build_object('order_id',current_setting('delivery_test.os'),'request_id',gen_random_uuid(),'numero','CASH001','emissao',date_trunc('month',current_date)::date-1,'valor','100.00','parcelas',jsonb_build_array(jsonb_build_object('valor','100.00','vencimento',date_trunc('month',current_date)::date-1))))->>'id',true);
SELECT public.maintenance_finance_command('1b000000-0000-4000-8000-000000000001','release',jsonb_build_object('id',current_setting('delivery_test.invoice'),'version',(SELECT version FROM public.maintenance_finance_invoices WHERE id=current_setting('delivery_test.invoice')::uuid),'observacao','Conferência aprovada'));
SELECT set_config('delivery_test.payment',public.maintenance_finance_command('1b000000-0000-4000-8000-000000000001','pay',jsonb_build_object('id',current_setting('delivery_test.invoice'),'version',(SELECT version FROM public.maintenance_finance_invoices WHERE id=current_setting('delivery_test.invoice')::uuid),'request_id',gen_random_uuid(),'installment_id',(SELECT id FROM public.maintenance_finance_installments WHERE invoice_id=current_setting('delivery_test.invoice')::uuid),'valor','100.00','data_pagamento',date_trunc('month',current_date)::date-1,'metodo','pix'))->>'id',true);
SELECT public.maintenance_finance_command('1b000000-0000-4000-8000-000000000001','reverse',jsonb_build_object('id',current_setting('delivery_test.invoice'),'version',(SELECT version FROM public.maintenance_finance_invoices WHERE id=current_setting('delivery_test.invoice')::uuid),'request_id',gen_random_uuid(),'payment_id',current_setting('delivery_test.payment'),'observacao','Estorno realizado em outro mês'));
SELECT public.maintenance_finance_command('1b000000-0000-4000-8000-000000000001','cancel',jsonb_build_object('id',current_setting('delivery_test.invoice'),'version',(SELECT version FROM public.maintenance_finance_invoices WHERE id=current_setting('delivery_test.invoice')::uuid),'observacao','Nota cancelada após o estorno integral'));
SELECT set_config('delivery_test.cashflow',public.maintenance_cashflow('1b000000-0000-4000-8000-000000000001',jsonb_build_object('start',(date_trunc('month',current_date)-interval '1 month')::date,'end',current_date))::text,true);
SELECT delivery_test.assert((current_setting('delivery_test.cashflow')::jsonb->0->>'previsto')::numeric=0,'cancelled invoice removed from forecast');
SELECT delivery_test.assert((current_setting('delivery_test.cashflow')::jsonb->0->>'realizado')::numeric=100,'original payment remains in actual payment month');
SELECT delivery_test.assert((current_setting('delivery_test.cashflow')::jsonb->1->>'realizado')::numeric=-100,'reversal remains in actual reversal month');
ROLLBACK;
